"""Generate a separately named, still disposable-guarded closed proposal.
Never connects to a database. No automatic migrations consume this output.
"""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
parts=[]
for name in ['liquidity-fencing-disposable.sql','liquidity-authority-disposable.sql']:
 text=(ROOT/'docs/proposals'/name).read_text()
 # Preserve BOTH original database/user guards; combine into ONE transaction.
 text='\n'.join(line for line in text.splitlines() if line not in ['BEGIN;','COMMIT;'])
 text=text.replace('-- No public Liquidity tables, existing roles or grants are changed.', '-- Base fencing objects; the combined candidate also models sequence hardening.')
 text=text.replace('liquidity_proposal','liquidity_fencing_private')
 for old,new in [('lq_test_code_owner','liquidity_fencing_code_owner'),('lq_test_executor','liquidity_fencing_executor'),('lq_test_reviewer','liquidity_fencing_reviewer')]:
  text=text.replace(old,new)
 text=text.replace('NOLOGIN NOINHERIT','NOLOGIN PASSWORD NULL CONNECTION LIMIT 0 NOINHERIT')
 parts.append(text)
header='''-- GENERATED UNAPPLIED CLOSED SETUP; OUTSIDE AUTOMATIC MIGRATIONS.
-- Generated by tests/fixtures/liquidity-fencing/generate-closed.py.
-- Original disposable guards deliberately retained. NOT executable hosted SQL.
-- Eight empty tables, three closed roles; no enrollment or runtime bindings.
-- This candidate DOES model the narrow legacy sequence revoke locally.
BEGIN;
'''
out=header+'\n'.join(parts)+'\nCOMMIT;\n'
(ROOT/'docs/proposals/liquidity-closed-setup-candidate.sql').write_text(out)
